import ast
import sys
import os

class APIDocExtractor(ast.NodeVisitor):
    def __init__(self):
        self.endpoints = []

    def visit_FunctionDef(self, node):
        if node.name.startswith("get_") or node.name.startswith("post_"):
            docstring = ast.get_docstring(node) or ""
            params = [arg.arg for arg in node.args.args]
            returns = self._extract_return_type(node)

            self.endpoints.append({
                "name": node.name,
                "docstring": docstring,
                "params": params,
                "returns": returns
            })
        self.generic_visit(node)

    def _extract_return_type(self, node):
        if node.returns:
            try:
                return ast.unparse(node.returns)
            except AttributeError:
                return "Any"
        return "Any"

def generate_markdown_docs(endpoints):
    lines = []
    for endpoint in endpoints:
        lines.append(f"## {endpoint['name']}")
        lines.append("")
        lines.append(endpoint['docstring'])
        lines.append("")
        lines.append("### Parameters")
        if endpoint['params']:
            for param in endpoint['params']:
                lines.append(f"- `{param}`")
        else:
            lines.append("No parameters.")
        lines.append("")
        lines.append("### Returns")
        lines.append(f"- `{endpoint['returns']}`")
        lines.append("")
        lines.append("---")
        lines.append("")
    return "\n".join(lines)

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python script.py <path_to_python_file>", file=sys.stderr)
        sys.exit(1)

    file_path = sys.argv[1]

    if not os.path.isfile(file_path):
        print(f"Error: File '{file_path}' not found.", file=sys.stderr)
        sys.exit(1)

    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            source_code = f.read()

        tree = ast.parse(source_code)
        extractor = APIDocExtractor()
        extractor.visit(tree)

        markdown_output = generate_markdown_docs(extractor.endpoints)
        print(markdown_output)
    except SyntaxError as e:
        print(f"Error: Invalid Python syntax in '{file_path}': {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Error: An unexpected error occurred: {e}", file=sys.stderr)
        sys.exit(1)
